package com.phoenix.business.domain;
import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.*;
@Entity @Table(name="payments") @Getter @Setter @NoArgsConstructor
public class Payment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="receipt_number",nullable=false,unique=true) private String receiptNumber; @ManyToOne(optional=false) @JoinColumn(name="member_id") private Member member; @ManyToOne @JoinColumn(name="plan_id") private MembershipPlan plan; @Column(name="plan_name_snapshot",nullable=false) private String planNameSnapshot; @Column(name="period_start",nullable=false) private LocalDate periodStart; @Column(name="period_end",nullable=false) private LocalDate periodEnd; @Column(name="payment_date",nullable=false) private Instant paymentDate; @Column(nullable=false) private BigDecimal amount; @Enumerated(EnumType.STRING) @Column(nullable=false) private Method method; @Column(name="reference_note") private String referenceNote; @Enumerated(EnumType.STRING) @Column(nullable=false) private Status status=Status.PAID; @ManyToOne(optional=false) @JoinColumn(name="received_by") private User receivedBy; @Column(name="created_at",insertable=false,updatable=false) private Instant createdAt; public enum Method {CASH,UPI,CARD,BANK_TRANSFER,OTHER} public enum Status {PAID,PENDING,VOID} }
